package vn.edu.thuyetminh.media;

import java.io.IOException;
import java.io.InputStream;

import org.springframework.core.io.Resource;

/**
 * Binary storage abstraction. PostgreSQL stores only the returned storage key.
 * Implementations: {@link LocalMediaStorage} (dev/Docker volume). An object-storage implementation
 * (S3 / GCS / R2) can be added later without touching callers.
 */
public interface MediaStorage {

    /** Stores the bytes under {@code key}. Keys are relative, slash-separated, generated by the server. */
    void put(String key, InputStream data, long sizeBytes, String contentType) throws IOException;

    /** Returns a readable resource or throws {@link MediaNotFoundException}. */
    Resource get(String key);

    boolean exists(String key);

    void delete(String key) throws IOException;
}
